diff --git a/docs/install.md b/docs/install.md
index cbc59ab..a7eac3d 100644
--- a/docs/install.md
+++ b/docs/install.md
@@ -1,3 +1,9 @@
 # Installing

-Run `npx toolkit`. See `package.json` for the supported runtime range.
+Run `npx toolkit`. This package requires Node.js 22 LTS or later.
+
+## Runtime requirements
+
+We only support Node.js versions that receive active security patches. As of 2026, Node.js 20 and earlier have reached their end-of-life date and no longer receive security updates.
+
+If you're on an older Node.js version, upgrade to Node.js 22 LTS or later from https://nodejs.org.
diff --git a/scripts/check-engines.mjs b/scripts/check-engines.mjs
index ce51156..dad5ff3 100644
--- a/scripts/check-engines.mjs
+++ b/scripts/check-engines.mjs
@@ -5,6 +5,9 @@ const declared = pkg.engines?.node ?? "";
 const floor = Number(declared.replace(/[^0-9]/g, "").slice(0, 2));

 if (!Number.isInteger(floor) || floor < 22) {
+  const actual = process.version;
   console.error(`engines.node is "${declared}" — the floor may not go below 22`);
+  console.error(`You are using ${actual}, which is past its end-of-life date.`);
+  console.error(`Please upgrade to Node.js 22 LTS or later: https://nodejs.org`);
   process.exit(1);
 }
